    tests = [
        ("ABCBDAB", "BDCAB", "BCAB"),
        ("AGGTAB", "GXTXAYB", "GTAB"),
        ("abc", "abc", "abc"),
        ("abc", "def", ""),
        ("", "abc", ""),
        ("abc", "", ""),
        ("abcdef", "acf", "acf"),
        ("abcde", "ace", "ace"),
    ]

    all_passed = True
    for s1, s2, expected in tests:
        result = longest_common_subsequence(s1, s2)
        status = "PASS" if result == expected else "FAIL"
        if status == "FAIL":
            all_passed = False
        print(f"{status}: LCS('{s1}', '{s2}') = '{result}' (expected '{expected}')")

    # Also test length function
    assert lcs_length("ABCBDAB", "BDCAB") == 4
    assert lcs_length("abc", "def") == 0

    print(f"\n{'All tests passed!' if all_passed else 'Some tests FAILED.'}")
